"""Dense antique-engraving creature silhouettes for tools/genmaps.py."""
GOLD = "#c9a45c"

def art(kind, gold=GOLD):
    """Return SVG fragment; gold may be overridden to match genmaps palette."""
    raw = CREATURE_ART.get(kind) or CREATURE_ART["serpent"]
    if gold == GOLD:
        return raw
    return raw.replace(GOLD, gold)

